trait Renderer {                          // Implementor: primitives only
    fn circle(&self, r: f64);
}

struct CircleShape {                      // Abstraction owns the implementor
    renderer: Box<dyn Renderer>,          // fat pointer: data + vtable
    radius: f64,
}

impl CircleShape {
    fn draw(&self) { self.renderer.circle(self.radius); }
}

enum Renderer {                       // closed set of implementors
    Software(SoftwareRenderer),
    Cairo(CairoRenderer),
}

impl CircleShape {
    fn draw(&self) {
        match &self.renderer {        // exhaustive: no vtable, no allocation
            Renderer::Software(r) => r.circle(self.radius),
            Renderer::Cairo(r) => r.circle(self.radius),
        }
    }
}

